import{_ as o,o as d,c as a,a6 as c}from"./chunks/framework.DMOj2-2K.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),t={name:"changelog.md"};function i(n,e,s,r,l,u){return d(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to Cluub are documented here. The format follows <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and Cluub uses <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>. Before 1.0, minor versions may contain breaking changes to the language. Breaking changes will always be listed under <strong>Changed</strong> with a migration note.</p><h2 id="unreleased" tabindex="-1">[Unreleased] <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;[Unreleased]&quot;">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>The language is now called <strong>Cluub</strong> (it <em>clubs</em> frontend, backend and AI). Files use the <code>.clb</code> extension, the command is <code>cluub</code>, and the npm packages are <code>cluub</code> and <code>create-cluub</code>. Environment variables use the <code>CLUUB_</code> prefix (for example <code>CLUUB_AI</code>).</li><li>New logo: the <strong>uu</strong> of cluub are a cat&#39;s happy closed eyes. Brand colours stay Okabe–Ito (colour-blind safe), and every meaningful part of the logo has at least 3 : 1 contrast; the default app theme now uses the Cluub blue <code>#0072B2</code> (<code>#56B4E9</code> in dark mode).</li></ul><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Claude Code skills: 11 app skills (feature, backend, frontend, naming, tests, code review, PR review, fix issue, security, accessibility, debug) copied into every new project with a <code>CLAUDE.md</code>, plus 6 skills and a <code>CLAUDE.md</code> for contributors. See <a href="/guide/ai-assistants">Claude skills</a>.</li><li>Community files: <code>CONTRIBUTING.md</code>, <code>CODE_OF_CONDUCT.md</code>, <code>SECURITY.md</code>, issue and pull request templates, <code>CODEOWNERS</code>, Dependabot and <code>.editorconfig</code>.</li><li><code>npm create cluub@latest</code> (also pnpm, yarn and bun <code>create</code>) via the new <code>create-cluub</code> package. New projects get a <code>package.json</code> with <code>dev</code>, <code>test</code>, <code>check</code>, <code>build</code> and <code>start</code> scripts.</li><li>Bring-your-own-key AI: the <code>cluub ai</code> command (<code>set</code>, <code>use</code>, <code>test</code>, <code>remove</code>, status) manages developer keys in <code>.env</code> (mode 600, git-ignored).</li><li>End-user keys: the <code>aiKeys</code> app setting (<code>&quot;server&quot;</code>, <code>&quot;user&quot;</code>, <code>&quot;either&quot;</code>), the built-in <code>aikey</code> view element and the <code>hasAiKey()</code> built-in. End-user keys stay in the browser, travel in <code>X-Cluub-AI-Provider</code> / <code>X-Cluub-AI-Key</code> headers, are scoped to one request with <code>AsyncLocalStorage</code>, and are never stored or logged.</li><li>New error response <code>401 ai_key_required</code> when a feature needs the end user&#39;s key.</li><li>Docs: <a href="/guide/ai-keys">Your own AI keys</a>, <a href="/brand">Brand &amp; logo</a>, a larger FAQ and publishing instructions.</li><li>The project lives at <a href="https://github.com/cluub-lang/cluub" target="_blank" rel="noreferrer">github.com/cluub-lang/cluub</a> and the docs are published by GitHub Pages at <a href="https://cluub-lang.github.io/" target="_blank" rel="noreferrer">cluub-lang.github.io</a> on every push to <code>main</code>.</li></ul><h2 id="unreleased-1" tabindex="-1">[Unreleased] <a class="header-anchor" href="#unreleased-1" aria-label="Permalink to &quot;[Unreleased]&quot;">​</a></h2><p>Planned work is tracked on the <a href="/reference/roadmap">roadmap</a>: a language server and VS Code extension, full static types, database stores, auth, AI agents and streaming, a native compiler, <code>cluub fmt</code> and more deploy targets.</p><h2 id="_0-1-0-2026-11-23" tabindex="-1">[0.1.0] - 2026-11-23 <a class="header-anchor" href="#_0-1-0-2026-11-23" aria-label="Permalink to &quot;[0.1.0] - 2026-11-23&quot;">​</a></h2><p>The first public prototype. The compiler, runtime and CLI work end to end with zero dependencies.</p><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><h4 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h4><ul><li>Ten declaration kinds: <code>app</code>, <code>model</code>, <code>store</code>, <code>client</code>, <code>service</code>, <code>api</code>, <code>page</code>, <code>component</code>, <code>layout</code> and <code>test</code>.</li><li>Indentation-based blocks with exactly 2 spaces per level. Tabs are rejected (E001–E003).</li><li>Word operators: <code>is</code>, <code>is not</code>, <code>and</code>, <code>or</code>, <code>not</code>, <code>has</code>, <code>is empty</code>, <code>is one of</code>, <code>is greater than</code>, <code>is at least</code>, <code>plus</code>, <code>minus</code>, <code>times</code>, <code>divided by</code> and more. Symbol operators such as <code>==</code> and <code>&amp;&amp;</code> are errors that hint at the right word (E006).</li><li>Text interpolation with <code>{expr}</code>, multi-line <code>&quot;&quot;&quot;triple-quoted&quot;&quot;&quot;</code> text, lists, objects, <code>nothing</code>, <code>yes</code>/<code>no</code>, and numbers with <code>_</code> separators.</li><li>Statements: <code>let</code>, assignment, <code>return</code>, <code>require</code>, <code>fail … status</code>, <code>if / else if / else</code>, <code>for</code>, <code>while</code>, <code>try … catch</code>, <code>log</code> and <code>go to</code>.</li><li>List and text helpers: <code>.count</code>, <code>.first</code>, <code>.last</code>, <code>.where()</code>, <code>.map()</code>, <code>.sortBy()</code>, <code>.contains()</code>, <code>.add()</code>, <code>.upper()</code>, <code>.lower()</code>, <code>.trim()</code>.</li><li>Built-ins: <code>now()</code>, <code>today()</code>, <code>round()</code>, <code>text()</code>, <code>number()</code>, <code>uuid()</code>, <code>json()</code>, <code>random()</code>, <code>sleep()</code>, <code>env</code> (backend only) and <code>screen</code> (tests only).</li><li>Types: <code>text</code>, <code>number</code>, <code>bool</code>, <code>email</code>, <code>url</code>, <code>date</code>, <code>id</code>, <code>any</code>, <code>list of T</code>, model names and optional <code>T?</code>.</li></ul><h4 id="data-and-backend" tabindex="-1">Data and backend <a class="header-anchor" href="#data-and-backend" aria-label="Permalink to &quot;Data and backend&quot;">​</a></h4><ul><li>Models with the rules <code>required</code>, <code>min</code>, <code>max</code> and <code>one of</code>, custom messages, defaults, and precise validation messages. Unknown fields are rejected.</li><li>Stores in memory or saved to a JSON file (<code>saved in</code>), with <code>all</code>, <code>find</code>, <code>get</code>, <code>add</code>, <code>update</code>, <code>remove</code>, <code>where</code>, <code>count</code> and <code>clear</code>. File writes are atomic (temporary file, then rename).</li><li>Clients for outside HTTP APIs: base URL, headers, typed routes and a 15-second timeout.</li><li>Services with actions, <code>require</code> guards and dependency injection through <code>uses</code>.</li><li>Apis with <code>get</code>, <code>post</code>, <code>put</code>, <code>patch</code> and <code>delete</code> routes, path, query and body parameters, and automatic type validation (400 with the field name). Statuses are mapped automatically: 400, 404, 405, 413, 502 and 500.</li><li>A Node HTTP server with static file serving and a single-page-app fallback. Its security defaults are listed under <strong>Security</strong> below.</li><li>File stores load when the server starts, so a broken data file stops startup with a clear message.</li></ul><h4 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h4><ul><li>Pages with paths and path parameters, <code>title</code>, <code>layout</code>, <code>state</code>, <code>when loaded</code>, actions and views.</li><li>Stateless components with <code>takes</code> and <code>action</code> properties, and layouts with <code>slot</code>.</li><li>View elements: <code>heading</code>, <code>subheading</code>, <code>text</code>, <code>label</code>, <code>badge</code>, <code>item</code>, <code>button</code>, <code>link</code>, <code>image</code>, <code>input</code> (including <code>multiline</code>), <code>checkbox</code>, <code>select</code>, <code>row</code>, <code>column</code>, <code>card</code>, <code>box</code>, <code>grid</code>, <code>list</code>, <code>header</code>, <code>footer</code>, <code>nav</code>, <code>section</code>, <code>form</code>, <code>divider</code> and <code>spinner</code>, plus <code>for</code> and <code>if / else</code> in views.</li><li>Properties <code>placeholder</code>, <code>type</code>, <code>disabled</code>, <code>style</code>, <code>class</code>, <code>alt</code>, <code>options</code>, <code>multiline</code>, <code>to</code> and <code>label</code> (sets <code>aria-label</code>). Events <code>click</code>, <code>change</code>, <code>input</code>, <code>enter</code>, <code>submit</code>, <code>blur</code> and <code>focus</code>, plus multi-line event blocks.</li><li>A virtual DOM runtime with reactive page state, a client-side router, a typed api client that pages call by name, automatic awaiting, and error toasts (<code>role=&quot;alert&quot;</code>).</li><li>Text always rendered as text nodes, and <code>javascript:</code> URLs replaced in <code>href</code> and <code>src</code>.</li><li>Accessibility: inputs and selects without a <code>label</code> use their placeholder as <code>aria-label</code>; <code>spinner</code> is <code>role=&quot;status&quot;</code> (&quot;Loading&quot;); the crash message is <code>role=&quot;alert&quot;</code>; focus moves to the page&#39;s <code>&lt;main&gt;</code> after client-side navigation; the <code>lang</code> app setting sets <code>&lt;html lang&gt;</code>; form-control borders use <code>--control-border</code> with at least 3:1 contrast. The <code>app</code> template labels its checkbox, delete button and priority select.</li><li>A built-in responsive theme with light and dark mode, customizable through <code>theme.css</code>. Files in <code>assets/</code> are served from <code>/assets/</code>.</li></ul><h4 id="architecture-and-diagnostics" tabindex="-1">Architecture and diagnostics <a class="header-anchor" href="#architecture-and-diagnostics" aria-label="Permalink to &quot;Architecture and diagnostics&quot;">​</a></h4><ul><li>Enforced folder layout (E301), layer rules page → api → service → store/client (E201–E203), backend-only AI and <code>env</code> (E204, E205), and hard-coded secret detection (E401).</li><li>Naming rules: PascalCase declarations (E102) and camelCase members (E103).</li><li>Name resolution with &quot;Did you mean …?&quot; hints (E104–E116), and suggestions that teach design: unused dependency (W101), oversized action (W102) or service (W103), missing <code>about</code> (W104), unused state (W105), a page without a view (W106), a layout without exactly one <code>slot</code> (W107) and an unknown app setting (W108).</li><li>E117: a view that calls an api, an action, a component callback or <code>sleep()</code> while drawing.</li><li>The app name must be PascalCase. Models and services may be named <code>R</code>, <code>B</code>, <code>T</code> or <code>h</code> without clashing with generated code.</li><li>Elm-style error output with a code frame, a caret and a hint. Parsing recovers per declaration, so one mistake doesn&#39;t hide the rest.</li></ul><h4 id="ai" tabindex="-1">AI <a class="header-anchor" href="#ai" aria-label="Permalink to &quot;AI&quot;">​</a></h4><ul><li><code>ask ai</code> with structured output (<code>as Model</code>, <code>as list of Model</code>, validated, with one retry), classification (<code>as one of [...]</code>), <code>using &quot;provider:model&quot;</code> and <code>with system</code>.</li><li>Providers: Claude, OpenAI, Gemini and Ollama, configured through <code>app.clb</code>, <code>CLUUB_AI</code>, <code>CLUUB_&lt;PROVIDER&gt;_MODEL</code> and <code>OLLAMA_HOST</code>. Live provider calls haven&#39;t been tested end to end for every provider.</li><li><code>cluub make</code>: AI writes or changes code, the compiler checks it, errors are fed back up to three times, and files are written only when the project compiles.</li></ul><h4 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h4><ul><li>A headless test runner: each test gets fresh in-memory stores, a fake AI and no network. Commands: <code>expect</code>, <code>expect … fails with</code>, <code>render</code>, <code>type … into</code>, <code>click</code>, <code>screen</code>, <code>request</code> and <code>go to</code>.</li><li>Automatic test generation for model rules, <code>require</code> guards, service actions, api validation, page rendering and button clicks, written to <code>tests/generated/</code> as readable Cluub.</li></ul><h4 id="tooling" tabindex="-1">Tooling <a class="header-anchor" href="#tooling" aria-label="Permalink to &quot;Tooling&quot;">​</a></h4><ul><li>CLI commands: <code>new</code> (templates <code>app</code>, <code>ai-chat</code>, <code>blank</code>), <code>dev</code> (with live reload), <code>check</code>, <code>test</code>, <code>build</code>, <code>start</code>, <code>explain --for po|ba|qa|dev</code>, <code>make</code>, <code>errors</code>, <code>version</code> and <code>help</code>.</li><li>A standalone build: <code>dist/</code> contains a copy of the runtime, and <code>node dist/start.mjs</code> runs the app with plain Node.js. The port comes from <code>--port</code> (for <code>cluub start</code>), then <code>PORT</code>, then the app&#39;s <code>port</code>, then 3000.</li><li><code>cluub explain</code> overviews for product owners, business analysts, QA and developers, generated from the code.</li><li>A TextMate grammar for syntax highlighting (<code>editors/cluub.tmLanguage.json</code>).</li><li>A VitePress documentation site with a live in-browser playground.</li><li>A repository self-test (<code>node tests/run.js</code>) that compiles and tests the templates and playground examples, compiles every <code>```cluub</code> sample in the docs, and runs the regression cases in <code>tests/regressions.js</code>.</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li>Api request bodies must be sent with <code>Content-Type: application/json</code> (otherwise <code>415</code>), which blocks cross-site request forgery through simple form or <code>text/plain</code> requests.</li><li>Bodies are read as bytes: the 1 MB limit counts bytes (<code>413</code> above it), and multi-byte UTF-8 text is never split.</li><li>Malformed percent-encoding in a URL returns <code>400 bad_url</code> instead of crashing the server.</li><li>Every response sends <code>X-Content-Type-Options: nosniff</code>, <code>Referrer-Policy: same-origin</code> and <code>X-Frame-Options: DENY</code>. HTML pages send a strict Content-Security-Policy with no inline script; the boot script is <code>/_cluub/boot.js</code>.</li><li>In production, automatic AI and network errors and unexpected errors reach the browser as generic messages. Details go to the server log. Messages written with <code>fail</code> are always shown.</li><li><code>.env</code> parsing: real environment variables win over <code>.env</code>; <code>export NAME=</code> lines and comments after unquoted values are supported.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><p>During documentation review, before release:</p><ul><li><code>Store.count()</code> works.</li><li><code>cluub start</code> uses the app&#39;s <code>port</code> setting when no <code>--port</code> or <code>PORT</code> is given.</li><li>Apis declared outside <code>/api</code> are served, and route matching prefers static path segments over <code>{params}</code>.</li><li>Live reload: each build has an id, and the browser reloads when it reconnects and sees a new one. <code>.env</code> changes trigger a rebuild in <code>cluub dev</code>.</li><li><code>CLUUB_AI</code> in the environment beats the app&#39;s <code>ai</code> setting.</li><li>CLI errors outside a project print one clean line; <code>cluub test --no-generate &lt;filter&gt;</code> keeps the filter; logs honor <code>NO_COLOR</code>.</li><li>The Ollama connection error names <code>OLLAMA_HOST</code>; <code>405</code> responses list every allowed method; the E301 hint suggests kebab-case file names.</li><li>Generated page tests skip buttons with a <code>disabled</code> rule and accept a click that navigates away. Apis can be called by name in tests, and <code>click</code> on a submit button triggers its form.</li></ul><p>Regression tests for each of these live in <code>tests/regressions.js</code>.</p><h3 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h3><ul><li>No authentication or sessions, no rate limiting, no CORS configuration and no HTTPS termination. See <a href="/guide/security#what-is-not-there-yet">Security</a>.</li><li>Return types, page state and component properties aren&#39;t type-checked. Values are checked at runtime boundaries (models, apis, stores).</li><li>Runtime errors point to generated JavaScript, not to <code>.clb</code> lines.</li><li>File stores keep everything in memory and support one server process per data folder.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/reference/roadmap">Status &amp; roadmap</a></li><li><a href="/contributing">Contributing</a></li><li><a href="/faq">FAQ</a></li></ul>',36)])])}const m=o(t,[["render",i]]);export{p as __pageData,m as default};
